                if (pos < 2.5) ink = vec3(0.95, 0.95, 1.0);         // note
                else if (pos < 5.5) ink = vec3(0.35, 0.85, 1.0);    // instrument
                else if (pos < 8.5) ink = vec3(0.45, 1.0, 0.5);     // volume
                else ink = vec3(1.0, 0.6, 0.3);                      // effect
